namespace AlpineQuestPort {
    internal static class CachedSourceVariants {
        public static MapSource Dem(){return new MapSource{Id="terrain-dem",Name="Матрица высот DEM",Group="Высоты",MinZoom=0,MaxZoom=14,Template="https://s3.amazonaws.com/elevation-tiles-prod/terrarium/{z}/{x}/{y}.png"};}
        public static List<MapSource> Find(List<MapSource> sources,List<CachedFragment> tiles,MapSource current){var result=new List<MapSource>();var present=new HashSet<string>(tiles.Select(t=>t.Source));foreach(var source in sources.Concat(new[]{current,Dem()}))foreach(string language in new[]{source.Language,"x-local","ru","en","uk","de","fr"}.Distinct()){
            var variant=source.Copy();variant.Language=language;if(!present.Contains(variant.CacheKey)&&variant.CacheKey!=current.CacheKey)continue;if(result.Any(s=>s.CacheKey==variant.CacheKey))continue;variant.Name=source.Name+" ["+language+"]";result.Add(variant);
        }return result.OrderBy(s=>s.Group).ThenBy(s=>s.Name).ToList();}
        public static List<CachedFragment> ScanWithDem(string root){var tiles=TileCacheInventory.Scan(root);string dem=Path.Combine(Path.GetDirectoryName(root),"elevation-cache");if(!Directory.Exists(dem))return tiles;string key=Dem().CacheKey;foreach(var file in WorkspaceArchive.SafeFiles(dem)){string relative=file.Substring(dem.Length+1).Replace('\\','/');if(!Regex.IsMatch(relative,@"^\d{1,2}/\d+/\d+\.png$"))continue;var p=relative.Split('/');int z=int.Parse(p[0]),x=int.Parse(p[1]),y=int.Parse(Path.GetFileNameWithoutExtension(p[2]));if(z>14||x>=(1<<z)||y>=(1<<z))continue;var info=new FileInfo(file);tiles.Add(new CachedFragment{Source=key,Z=z,X=x,Y=y,Bytes=info.Length,Written=info.LastWriteTimeUtc,Path=file});}return tiles;}
    }
    internal static class WorkspaceArchive {
        static readonly string[] Configs={"view-settings.xml","preferences.xml","layers.xml","group-visibility.xml","custom-maps.xml","favorites.xml","visibility.xml","offline-areas.xml"};
        static bool Plain(string path){return (File.GetAttributes(path)&FileAttributes.ReparsePoint)==0;}
        public static IEnumerable<string> SafeFiles(string root){if(!Directory.Exists(root)||!Plain(root))yield break;foreach(string file in Directory.EnumerateFiles(root))if(Plain(file))yield return file;foreach(string dir in Directory.EnumerateDirectories(root))foreach(string file in SafeFiles(dir))yield return file;}
        static bool Allowed(string name){if(name=="workspace.gpx"||name=="workspace.backup.gpx"||Configs.Contains(name))return true;return Regex.IsMatch(name,@"^maps/[a-zA-Z0-9_.-]+\.aqx$")||Regex.IsMatch(name,@"^tile-cache-v2/[A-Fa-f0-9]{20}/\d{1,2}/\d+/\d+\.png(\.meta|\.keep)?$")||Regex.IsMatch(name,@"^elevation-cache/\d{1,2}/\d+/\d+\.png(\.meta|\.keep)?$");}
        static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","");}
        public static Dictionary<string,byte[]> Capture(string folder,byte[] snapshot){var files=new Dictionary<string,byte[]>();string temporary=Path.Combine(folder,"backup-snapshot-"+Guid.NewGuid().ToString("N")+".gpx");try{MapFiles.SaveGpx(DocumentSnapshot.Restore(snapshot),temporary);files.Add("workspace.gpx",File.ReadAllBytes(temporary));}finally{if(File.Exists(temporary))File.Delete(temporary);}foreach(var name in Configs.Concat(new[]{"workspace.backup.gpx"}))if(File.Exists(Path.Combine(folder,name)))files[name]=File.ReadAllBytes(Path.Combine(folder,name));foreach(var file in SafeFiles(Path.Combine(folder,"maps"))){string name="maps/"+Path.GetFileName(file);if(Allowed(name))files[name]=File.ReadAllBytes(file);}return files;}
        public static void Export(string path,string folder,Dictionary<string,byte[]> files,bool includeCache){path=Path.GetFullPath(path);string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";var manifest=new XElement("mapdesk-backup",new XAttribute("version",1),new XAttribute("createdUtc",DateTime.UtcNow.ToString("o")));
            try{using(var stream=new FileStream(temp,FileMode.CreateNew))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create)){
                long totalBytes=0;int entryCount=0;
                Action<string,byte[]> add=delegate(string name,byte[] bytes){if(!Allowed(name))throw new InvalidDataException("Недопустимый файл копии: "+name);if(bytes.LongLength>128L*1024*1024||(totalBytes+=bytes.LongLength)>20L*1024*1024*1024||++entryCount>999999)throw new InvalidDataException("Слишком большая копия. Перенесите кэш отдельно.");var entry=zip.CreateEntry(name,CompressionLevel.Fastest);using(var output=entry.Open())output.Write(bytes,0,bytes.Length);manifest.Add(new XElement("file",new XAttribute("name",name),new XAttribute("size",bytes.Length),new XAttribute("sha256",Hash(bytes))));};
                foreach(var pair in files)add(pair.Key,pair.Value);
                if(includeCache)foreach(string sub in new[]{"tile-cache-v2","elevation-cache"})foreach(var file in SafeFiles(Path.Combine(folder,sub))){string name=file.Substring(folder.TrimEnd('\\').Length+1).Replace('\\','/');if(!Allowed(name))continue;byte[] bytes;try{bytes=File.ReadAllBytes(file);}catch(FileNotFoundException){continue;}add(name,bytes);}
                using(var description=new MemoryStream()){manifest.Save(description);if(description.Length>64L*1024*1024)throw new InvalidDataException("Слишком много файлов в копии.");description.Position=0;using(var output=zip.CreateEntry("manifest.xml").Open())description.CopyTo(output);}
            }if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}
        }
        public static string Restore(string archive,string parent){parent=Path.GetFullPath(parent);Directory.CreateDirectory(parent);if(!Plain(parent))throw new InvalidDataException("Выберите обычную папку, а не ссылку.");string staging=Path.Combine(parent,"MapDesk-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8)+".partial");Directory.CreateDirectory(staging);
            try{using(var file=File.OpenRead(archive))using(var zip=new ZipArchive(file,ZipArchiveMode.Read)){
                if(zip.Entries.Count>1000000)throw new InvalidDataException("Слишком много файлов в копии.");var entries=new Dictionary<string,ZipArchiveEntry>(StringComparer.OrdinalIgnoreCase);long total=0;
                foreach(var entry in zip.Entries){string name=entry.FullName;if(name!="manifest.xml"&&!Allowed(name)||name.Contains("..")||name.Contains('\\')||entries.ContainsKey(name))throw new InvalidDataException("Недопустимый путь в архиве.");if(entry.Length>128L*1024*1024||(total+=entry.Length)>20L*1024*1024*1024)throw new InvalidDataException("Копия превышает поддерживаемый размер.");entries.Add(name,entry);}
                ZipArchiveEntry manifestEntry;if(!entries.TryGetValue("manifest.xml",out manifestEntry)||manifestEntry.Length>64L*1024*1024)throw new InvalidDataException("Нет корректного описания резервной копии.");XElement manifest;using(var input=manifestEntry.Open())using(var reader=XmlReader.Create(input,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=64L*1024*1024}))manifest=XElement.Load(reader);if(manifest.Name!="mapdesk-backup"||(int?)manifest.Attribute("version")!=1)throw new InvalidDataException("Неизвестная версия копии.");var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                foreach(var record in manifest.Elements("file")){string name=(string)record.Attribute("name");ZipArchiveEntry entry;if(name==null||!Allowed(name)||!seen.Add(name)||!entries.TryGetValue(name,out entry)||(long?)record.Attribute("size")!=entry.Length)throw new InvalidDataException("Описание файлов не совпадает с архивом.");byte[] bytes;using(var input=entry.Open())using(var memory=new MemoryStream()){byte[] buffer=new byte[65536];int n;while((n=input.Read(buffer,0,buffer.Length))>0){if(memory.Length+n>entry.Length)throw new InvalidDataException("Неверный размер файла.");memory.Write(buffer,0,n);}bytes=memory.ToArray();}if(bytes.LongLength!=entry.Length||Hash(bytes)!=(string)record.Attribute("sha256"))throw new InvalidDataException("Повреждён файл: "+name);string destination=Path.GetFullPath(Path.Combine(staging,name.Replace('/',Path.DirectorySeparatorChar)));if(!destination.StartsWith(staging+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Путь вне папки восстановления.");Directory.CreateDirectory(Path.GetDirectoryName(destination));File.WriteAllBytes(destination,bytes);}
                if(seen.Count!=entries.Count-1||!seen.Contains("workspace.gpx"))throw new InvalidDataException("Неполная резервная копия.");MapFiles.Load(Path.Combine(staging,"workspace.gpx"));foreach(string name in Configs.Where(seen.Contains))using(var reader=XmlReader.Create(Path.Combine(staging,name),new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=4*1024*1024}))XDocument.Load(reader);if(seen.Contains("view-settings.xml"))ViewSettings.Load(Path.Combine(staging,"view-settings.xml"));if(seen.Contains("layers.xml"))LayerConfiguration.Load(Path.Combine(staging,"layers.xml"));if(seen.Contains("custom-maps.xml"))UserMapCatalog.Load(Path.Combine(staging,"custom-maps.xml"));
            }string destinationFolder=staging.Substring(0,staging.Length-8);Directory.Move(staging,destinationFolder);return destinationFolder;}catch{if(Path.GetFullPath(staging).StartsWith(parent.TrimEnd('\\')+"\\MapDesk-",StringComparison.OrdinalIgnoreCase)&&Directory.Exists(staging))Directory.Delete(staging,true);throw;}
        }
    }
    internal static class FavoriteSources {
        public static List<MapSource> Load(string path){return AtomicSettings.Recover(path,LoadCore);}
        static List<MapSource> LoadCore(string path){if(!File.Exists(path))return new List<MapSource>();var settings=new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=2*1024*1024};using(var r=XmlReader.Create(path,settings)){var config=(LayerConfiguration)new System.Xml.Serialization.XmlSerializer(typeof(LayerConfiguration)).Deserialize(r);foreach(var layer in config.Layers)layer.Validate();return config.Layers.Select(l=>l.Source).ToList();}}
        public static void Save(string path,List<MapSource> items){new LayerConfiguration{Layers=items.Select(s=>new LayerDefinition{Source=s.Copy()}).ToList()}.Save(path);}
    }
    sealed partial class MainForm {
        bool preferencesReady,archiveBusy;
        string observedView,savedView;
        DateTime viewChanged;
        List<MapSource> favorites=new List<MapSource>();
        ToolStripDropDownButton favoriteMenu;
        ToolStripButton coverageButton;
        void RememberSource(){if(!preferencesReady||previewMode)return;try{SavePreferences();}catch(Exception ex){Diagnostics.Record("WorkspaceTools.failure",ex);SetMessage("Источник не сохранён: "+ex.Message);}}
        void RememberView(){if(!preferencesReady||previewMode)return;string key=currentSource.CacheKey+"|"+currentCrs.Id+"|"+map.Center.Lat.ToString("R",CultureInfo.InvariantCulture)+"|"+map.Center.Lon.ToString("R",CultureInfo.InvariantCulture)+"|"+map.Zoom;if(key!=observedView){observedView=key;viewChanged=DateTime.UtcNow;return;}if(key==savedView||(DateTime.UtcNow-viewChanged).TotalSeconds<1)return;try{SavePreferences();savedView=key;}catch(Exception ex){Diagnostics.Record("WorkspaceTools.failure",ex);viewChanged=DateTime.UtcNow;SetMessage("Положение карты не сохранено: "+ex.Message);}}
        void InitializeWorkspaceTools(ToolStrip tools,ToolStrip sourceTools){
            var workspaceMenu=new ToolStripDropDownButton("Копия…");workspaceMenu.ToolTipText="Резервная копия и перенос рабочего пространства";workspaceMenu.DropDownItems.Add("Сохранить рабочее пространство…",null,async delegate{await ExportWorkspace();});workspaceMenu.DropDownItems.Add("Восстановить копию в отдельную папку…",null,async delegate{await RestoreWorkspace();});workspaceMenu.DropDownItems.Add("Показать папку данных",null,delegate{System.Diagnostics.Process.Start("explorer.exe",dataDir);});tools.Items.Add(workspaceMenu);
            FormClosing+=delegate(object sender,FormClosingEventArgs e){if(archiveBusy){e.Cancel=true;SetMessage("Дождитесь окончания работы с резервной копией.");}};
            favoriteMenu=new ToolStripDropDownButton("★ Карты");sourceTools.Items.Insert(1,favoriteMenu);try{favorites=FavoriteSources.Load(Path.Combine(dataDir,"favorites.xml"));}catch(Exception ex){Diagnostics.Record("WorkspaceTools.failure",ex);SetMessage("Избранное не прочитано: "+ex.Message);}favoriteMenu.DropDownOpening+=delegate{FillFavorites();};
            var presets=new ToolStripDropDownButton("Вид");foreach(string name in new[]{"Обзор","Измерения","Профиль"}){string preset=name;presets.DropDownItems.Add(name,null,delegate{ApplyPreset(preset);});}sourceTools.Items.Add(presets);
            coverageButton=new ToolStripButton("Покрытие"){CheckOnClick=true,Visible=false,ToolTipText="Зелёные участки сохранены на указанном масштабе. Отключить наложение."};coverageButton.CheckedChanged+=delegate{map.ShowCoverage=coverageButton.Checked;map.RequestFrame();};sourceTools.Items.Add(coverageButton);
        }
        void FillFavorites(){favoriteMenu.DropDownItems.Clear();bool exists=favorites.Any(s=>s.CacheKey==currentSource.CacheKey);favoriteMenu.DropDownItems.Add(exists?"Убрать текущую карту из избранного":"Добавить текущую карту в избранное",null,delegate{var next=favorites.Select(s=>s.Copy()).ToList();if(exists)next.RemoveAll(s=>s.CacheKey==currentSource.CacheKey);else next.Add(currentSource.Copy());try{FavoriteSources.Save(Path.Combine(dataDir,"favorites.xml"),next);favorites=next;}catch(Exception ex){Diagnostics.Record("WorkspaceTools.failure",ex);SetMessage("Избранное не сохранено: "+ex.Message);}});favoriteMenu.DropDownItems.Add(new ToolStripSeparator());foreach(var item in favorites){var chosen=item.Copy();favoriteMenu.DropDownItems.Add(chosen.Name+" ["+chosen.Language+"]",null,delegate{SetSource(chosen);});}}
        internal void ApplyPreset(string name){settings.Perspective=false;settings.Rotation=0;settings.DataCards=true;settings.ScaleBar=true;settings.RangeRings=name=="Измерения";settings.PointNames=name!="Обзор";settings.Elevation=name=="Профиль";ApplySettings();if(!previewMode)try{settings.Save(Path.Combine(dataDir,"view-settings.xml"));}catch(Exception ex){Diagnostics.Record("WorkspaceTools.failure",ex);SetMessage("Вид не сохранён: "+ex.Message);}SetMessage("Вид: "+name+(name=="Профиль"?". Выберите точку и включите «Луч».":""));}
        void ShowCoverage(MapSource source,List<CachedFragment> tiles,int z){if(tiles.Count==0)return;online.Checked=false;bool dem=source.Id=="terrain-dem";if(!dem)SetSource(source);else{settings.Elevation=true;ApplySettings();}map.CachedCoverage=tiles;map.CoverageSourceKey=dem?null:source.CacheKey;map.CoverageLevel=z;map.CoverageIsDem=dem;map.ShowCoverage=true;coverageButton.Visible=true;coverageButton.Checked=true;var center=map.Center;var nearest=tiles.OrderBy(t=>GeoMath.DistanceMeters(center,new GeoPoint(GeoMath.PixelToLat(t.Y*256.0+128,z),GeoMath.PixelToLon(t.X*256.0+128,z)))).First();map.GoTo(new GeoPoint(GeoMath.PixelToLat(nearest.Y*256.0+128,z),GeoMath.PixelToLon(nearest.X*256.0+128,z)),z);SetMessage("Офлайн-покрытие "+(dem?"DEM":"карты")+" Z"+z+". Зелёный — файл сохранён. Другие масштабы смотрите через «Кэш…».");}
        async Task ExportWorkspace(){if(archiveBusy)return;using(var options=new BackupOptionsDialog()){if(options.ShowDialog(this)!=DialogResult.OK)return;using(var dialog=new SaveFileDialog{Filter="Рабочее пространство MapDesk|*.mapdesk",FileName="MapDesk-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".mapdesk"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;archiveBusy=true;try{SavePreferences();settings.Save(Path.Combine(dataDir,"view-settings.xml"));var files=WorkspaceArchive.Capture(dataDir,DocumentSnapshot.Capture(map.CommittedDocument()));SetMessage("Создание резервной копии…");await BackgroundJobs.Run("WorkspaceTools",()=>WorkspaceArchive.Export(dialog.FileName,dataDir,files,options.IncludeCache));SetMessage("Резервная копия сохранена: "+dialog.FileName);}catch(Exception ex){Diagnostics.Record("WorkspaceTools.failure",ex);MessageBox.Show(this,ex.Message,"Копия не сохранена");}finally{archiveBusy=false;}}}}
        async Task RestoreWorkspace(){if(archiveBusy)return;using(var open=new OpenFileDialog{Filter="Рабочее пространство MapDesk|*.mapdesk"}){if(open.ShowDialog(this)!=DialogResult.OK)return;using(var folder=new FolderBrowserDialog{Description="Выберите место для новой отдельной папки. Текущий набор останется на месте."}){if(folder.ShowDialog(this)!=DialogResult.OK)return;archiveBusy=true;try{SetMessage("Проверка и восстановление копии…");string restored=await BackgroundJobs.Run("WorkspaceTools",()=>WorkspaceArchive.Restore(open.FileName,folder.SelectedPath));SetMessage("Копия восстановлена: "+restored);System.Diagnostics.Process.Start(Application.ExecutablePath,"--data-dir \""+restored+"\"");}catch(Exception ex){Diagnostics.Record("WorkspaceTools.failure",ex);MessageBox.Show(this,ex.Message,"Копия не восстановлена");}finally{archiveBusy=false;}}}}
    }
    sealed class BackupOptionsDialog:Form {
        readonly CheckBox cache=new CheckBox{Text="Включить кэш карт и матрицу высот DEM",AutoSize=true,Location=new Point(18,104)};
        public bool IncludeCache {get{return cache.Checked;}}
        public BackupOptionsDialog(){Text="Резервная копия рабочего пространства";ClientSize=new Size(570,215);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;Controls.Add(new Label{Text="Будут сохранены объекты, группы, настройки, источники и избранное.\nНезавершённая правка в копию не входит.\nПри восстановлении создаётся отдельная папка и открывается новое окно.",Location=new Point(18,18),Size=new Size(535,78)});Controls.Add(cache);Controls.Add(new Label{Text="Ключи доступа в URL источников также попадут в копию.",Location=new Point(18,135),AutoSize=true});var ok=new Button{Text="Продолжить",Location=new Point(304,173),Size=new Size(125,30),DialogResult=DialogResult.OK};var cancel=new Button{Text="Отмена",Location=new Point(439,173),Size=new Size(112,30),DialogResult=DialogResult.Cancel};Controls.Add(ok);Controls.Add(cancel);AcceptButton=ok;CancelButton=cancel;}
    }
    sealed partial class MapCanvas {
        internal List<CachedFragment> CachedCoverage=new List<CachedFragment>();
        internal bool ShowCoverage,CoverageIsDem;internal string CoverageSourceKey;internal int CoverageLevel;
        void DrawCachedCoverage(Graphics g){if(!ShowCoverage||CoverageSourceKey!=null&&CoverageSourceKey!=Tiles.Source.CacheKey)return;using(var fill=new SolidBrush(Color.FromArgb(65,35,185,95)))using(var line=new Pen(Color.FromArgb(165,15,135,60),1)){foreach(var tile in CachedCoverage){double west=GeoMath.PixelToLon(tile.X*256.0,tile.Z),east=GeoMath.PixelToLon((tile.X+1)*256.0,tile.Z),north=GeoMath.PixelToLat(tile.Y*256.0,tile.Z),south=GeoMath.PixelToLat((tile.Y+1)*256.0,tile.Z);var polygon=new[]{ToScreen(new GeoPoint(north,west)),ToScreen(new GeoPoint(north,east)),ToScreen(new GeoPoint(south,east)),ToScreen(new GeoPoint(south,west))};if(polygon.Any(p=>!GeoMath.IsFinite(p.X)||!GeoMath.IsFinite(p.Y)))continue;float minX=polygon.Min(p=>p.X),maxX=polygon.Max(p=>p.X),minY=polygon.Min(p=>p.Y),maxY=polygon.Max(p=>p.Y);if(maxX<0||minX>Width||maxY<0||minY>Height||maxX-minX>Width*4||maxY-minY>Height*4)continue;g.FillPolygon(fill,polygon);g.DrawPolygon(line,polygon);}}using(var font=new Font("Segoe UI",9)){string text=(CoverageIsDem?"DEM":"Карта")+" · сохранённые участки Z"+CoverageLevel;var size=g.MeasureString(text,font);g.FillRectangle(Brushes.White,8,Height-60,size.Width+12,25);g.DrawString(text,font,Brushes.DarkGreen,14,Height-56);}}
    }
}



